class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function ambiguousCoordinates($s) {
        $digits = substr($s, 1, -1);
        $n = strlen($digits);
        $result = [];

        $representations = function ($part) {
            $length = strlen($part);
            $forms = [];

            if ($length === 1 || $part[0] !== '0') {
                $forms[] = $part;
            }

            // Decimal representations cannot end in zero.
            if ($part[$length - 1] === '0') {
                return $forms;
            }

            for ($i = 1; $i < $length; $i++) {
                // Only a single zero is allowed before the decimal point.
                if ($i > 1 && $part[0] === '0') {
                    break;
                }

                $forms[] = substr($part, 0, $i) . '.' . substr($part, $i);
            }

            return $forms;
        };

        for ($split = 1; $split < $n; $split++) {
            $left = $representations(substr($digits, 0, $split));
            $right = $representations(substr($digits, $split));

            foreach ($left as $x) {
                foreach ($right as $y) {
                    $result[] = '(' . $x . ', ' . $y . ')';
                }
            }
        }

        return $result;
    }
}
