                $id = array_pop($stack);
                $r = intdiv($id, $n);
                $c = $id % $n;
                ++$count;

                if ($r > 0 && $grid[$r - 1][$c] === 1) {
                    $grid[$r - 1][$c] = 2;
                    $stack[] = $id - $n;
                }
                if ($r + 1 < $m && $grid[$r + 1][$c] === 1) {
                    $grid[$r + 1][$c] = 2;
                    $stack[] = $id + $n;
