                if ($c > 0 && $grid[$r][$c - 1] === 1) {
                    $grid[$r][$c - 1] = 2;
                    $stack[] = $id - 1;
                }
                if ($c + 1 < $n && $grid[$r][$c + 1] === 1) {
                    $grid[$r][$c + 1] = 2;
                    $stack[] = $id + 1;
                }
            }

            return $count;
        };

        // Find all bricks still connected to the roof.
        for ($c = 0; $c < $n; ++$c) {
            if ($grid[0][$c] === 1) {
                $stabilize(0, $c);
            }
        }

        for ($i = $k - 1; $i >= 0; --$i) {
            if (!$removed[$i]) {
                continue;
