    function numSmallerByFrequency($queries, $words) {
        $frequency = function ($s) {
            $smallest = 123;
            $count = 0;
            $length = strlen($s);

            for ($i = 0; $i < $length; $i++) {
                $character = ord($s[$i]);

                if ($character < $smallest) {
                    $smallest = $character;
                    $count = 1;
                } elseif ($character === $smallest) {
                    $count++;
