        $suffix = array_fill(0, 12, 0);

        foreach ($words as $word) {
            $suffix[$frequency($word)]++;
        }

        for ($i = 10; $i >= 0; $i--) {
            $suffix[$i] += $suffix[$i + 1];
        }

        $answer = [];
        foreach ($queries as $query) {
            $answer[] = $suffix[$frequency($query) + 1];
        }

        return $answer;
    }
