     * @return Boolean
     */
    function canCross($stones) {
        $n = count($stones);

        if ($stones[1] !== 1) {
            return false;
        }

        $indexByPosition = [];
        foreach ($stones as $i => $position) {
            // No jump crossing this gap can be longer than i.
            if ($i > 0 && $position - $stones[$i - 1] > $i) {
                return false;
            }
            $indexByPosition[$position] = $i;
        }

        // reachable[i] contains all possible last jumps onto stone i.
        $reachable = array_fill(0, $n, []);
        $reachable[0][0] = true;

        for ($i = 0; $i < $n; $i++) {
            foreach ($reachable[$i] as $jump => $unused) {
                for ($nextJump = max(1, $jump - 1);
                     $nextJump <= $jump + 1;
                     $nextJump++) {
                    $nextPosition = $stones[$i] + $nextJump;

                    if (!isset($indexByPosition[$nextPosition])) {
                        continue;
                    }

                    $nextIndex = $indexByPosition[$nextPosition];
                    if ($nextIndex === $n - 1) {
                        return true;
                    }

                    $reachable[$nextIndex][$nextJump] = true;
                }
            }

            // Forward-only jumps never need this state again.
            unset($reachable[$i]);
        }

        return false;
    }
