    function licenseKeyFormatting($s, $k) {
        $s = strtoupper(str_replace('-', '', $s));
        $length = strlen($s);

        if ($length === 0) {
            return '';
        }

        $firstLength = $length % $k;
        if ($firstLength === 0) {
            $firstLength = $k;
