class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxScore($nums) {
        $m = count($nums);
        $pairMasks = [];
        $pairGcds = [];

        for ($i = 0; $i < $m; $i++) {
            for ($j = $i + 1; $j < $m; $j++) {
                $a = $nums[$i];
                $b = $nums[$j];

                while ($b !== 0) {
                    $remainder = $a % $b;
                    $a = $b;
                    $b = $remainder;
                }

                $pairMasks[] = (1 << $i) | (1 << $j);
                $pairGcds[] = $a;
            }
        }

        $size = 1 << $m;
        $bitCounts = array_fill(0, $size, 0);

        for ($mask = 1; $mask < $size; $mask++) {
            $bitCounts[$mask] = $bitCounts[$mask >> 1] + ($mask & 1);
        }

        // dp[mask] is the best score after removing the marked elements.
        $dp = array_fill(0, $size, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $size - 1; $mask++) {
            if ($dp[$mask] < 0) {
                continue;
            }

            $operation = intdiv($bitCounts[$mask], 2) + 1;

            foreach ($pairMasks as $index => $pairMask) {
                if (($mask & $pairMask) !== 0) {
                    continue;
                }

                $nextMask = $mask | $pairMask;
                $score = $dp[$mask] + $operation * $pairGcds[$index];

                if ($score > $dp[$nextMask]) {
                    $dp[$nextMask] = $score;
                }
            }
        }

        return $dp[$size - 1];
    }
}
