     * @param Integer[] $batteries
     * @return Integer
     */
    function maxRunTime($n, $batteries) {
        $total = 0;
        foreach ($batteries as $capacity) {
            $total += $capacity;
        }

        $low = 0;
        $high = intdiv($total, $n);

        while ($low < $high) {
            $mid = $low + intdiv($high - $low + 1, 2);
            $required = $mid * $n;
            $available = 0;

            foreach ($batteries as $capacity) {
                $available += min($capacity, $mid);
                if ($available >= $required) {
                    break;
                }
            }

            if ($available >= $required) {
                $low = $mid;
            } else {
                $high = $mid - 1;
            }
        }

        return $low;
    }
}
