    function minDays($bloomDay, $m, $k) {
        $n = count($bloomDay);

        if ($m > intdiv($n, $k)) {
            return -1;
        }

        $left = min($bloomDay);
        $right = max($bloomDay);

        while ($left < $right) {
            $mid = $left + intdiv($right - $left, 2);
            $bouquets = 0;
            $consecutive = 0;

            foreach ($bloomDay as $day) {
