    function numOfWays($nums) {
        $mod = 1000000007;
        $n = count($nums);

        if ($n <= 2) {
            return 0;
        }

        // Nodes are indexed by insertion order.
        $left = array_fill(0, $n, -1);
        $right = array_fill(0, $n, -1);

        for ($i = 1; $i < $n; $i++) {
            $current = 0;

            while (true) {
                if ($nums[$i] < $nums[$current]) {
                    if ($left[$current] === -1) {
                        $left[$current] = $i;
                        break;
                    }
                    $current = $left[$current];
                } else {
                    if ($right[$current] === -1) {
                        $right[$current] = $i;
                        break;
                    }
                    $current = $right[$current];
                }
            }
        }

        // Factorials and inverse factorials for binomial coefficients.
        $factorial = array_fill(0, $n + 1, 1);
        for ($i = 1; $i <= $n; $i++) {
            $factorial[$i] = ($factorial[$i - 1] * $i) % $mod;
        }

        $inverseFactorial = array_fill(0, $n + 1, 1);
        $base = $factorial[$n];
        $exponent = $mod - 2;
        $inverse = 1;

        while ($exponent > 0) {
            if (($exponent & 1) === 1) {
                $inverse = ($inverse * $base) % $mod;
            }
            $base = ($base * $base) % $mod;
            $exponent = intdiv($exponent, 2);
        }

        $inverseFactorial[$n] = $inverse;
        for ($i = $n; $i >= 1; $i--) {
            $inverseFactorial[$i - 1] =
                ($inverseFactorial[$i] * $i) % $mod;
        }

        $size = array_fill(0, $n, 1);
        $ways = array_fill(0, $n, 1);

        // Every child has a larger index, so reverse order is bottom-up.
        for ($i = $n - 1; $i >= 0; $i--) {
            $l = $left[$i];
            $r = $right[$i];

            $leftSize = $l === -1 ? 0 : $size[$l];
            $rightSize = $r === -1 ? 0 : $size[$r];

            $size[$i] = 1 + $leftSize + $rightSize;

            $count = $factorial[$leftSize + $rightSize];
            $count = ($count * $inverseFactorial[$leftSize]) % $mod;
            $count = ($count * $inverseFactorial[$rightSize]) % $mod;

