     * @param Integer $k
     * @return Boolean
     */
    function canPartitionKSubsets($nums, $k) {
        $sum = array_sum($nums);
        if ($sum % $k !== 0) {
            return false;
        }
        if ($k === 1) {
            return true;
        }

        $target = intdiv($sum, $k);
        sort($nums, SORT_NUMERIC);
        $n = count($nums);

        if ($nums[$n - 1] > $target) {
            return false;
        }

        $states = 1 << $n;

        // dp[mask] is the current subset sum, or -1 if unreachable.
        $dp = array_fill(0, $states, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $states; $mask++) {
            if ($dp[$mask] === -1) {
                continue;
            }

            for ($i = 0; $i < $n; $i++) {
                $nextSum = $dp[$mask] + $nums[$i];
                if ($nextSum > $target) {
                    break;
