                $bit = 1 << $i;
                if (($mask & $bit) !== 0) {
                    continue;
                }

                $nextMask = $mask | $bit;
                $dp[$nextMask] = ($nextSum === $target) ? 0 : $nextSum;
            }
        }

        return $dp[$states - 1] === 0;
    }
