     * @return Integer
     */
    function maxSizeSlices($slices) {
        $length = count($slices);
        $picks = intdiv($length, 3);
        $negativeInfinity = -1000000000;
        $answer = 0;

        // A circular selection cannot contain both the first and last slices.
        for ($start = 0; $start <= 1; $start++) {
            $end = $start + $length - 2;

            $twoBack = array_fill(0, $picks + 1, $negativeInfinity);
            $twoBack[0] = 0;
            $oneBack = $twoBack;

            for ($i = $start; $i <= $end; $i++) {
                // Skipping this slice preserves the previous DP values.
                $current = $oneBack;
                $processed = $i - $start + 1;
                $limit = min($picks, intdiv($processed + 1, 2));

                for ($j = 1; $j <= $limit; $j++) {
                    // Taking this slice requires skipping its predecessor.
                    if ($twoBack[$j - 1] !== $negativeInfinity) {
                        $current[$j] = max(
                            $current[$j],
                            $twoBack[$j - 1] + $slices[$i]
                        );
                    }
                }

                $twoBack = $oneBack;
                $oneBack = $current;
            }

            $answer = max($answer, $oneBack[$picks]);
        }

        return $answer;
    }
