            if (isset($memo[$key])) {
                return $memo[$key];
            }

            if (substr($s1, $i, $length) === substr($s2, $j, $length)) {
                return $memo[$key] = true;
            }

            $counts = array_fill(0, 26, 0);
            for ($k = 0; $k < $length; $k++) {
                $counts[ord($s1[$i + $k]) - 97]++;
                $counts[ord($s2[$j + $k]) - 97]--;
            }

            foreach ($counts as $count) {
                if ($count !== 0) {
                    return $memo[$key] = false;
                }
            }

            for ($split = 1; $split < $length; $split++) {
                $remaining = $length - $split;

                if (
                    $dfs($i, $j, $split) &&
                    $dfs($i + $split, $j + $split, $remaining)
