    private $edges = [];
    private $terminal = [];
    private $nodeCount = 1;
    private $maxLength = 0;
    private $stream = '';

    /**
     * @param String[] $words
     */
    function __construct($words) {
        foreach ($words as $word) {
            $length = strlen($word);
            $this->maxLength = max($this->maxLength, $length);
            $node = 0;

            // Insert each word in reverse order.
            for ($i = $length - 1; $i >= 0; --$i) {
                $key = $node * 26 + ord($word[$i]) - 97;

                if (!isset($this->edges[$key])) {
                    $this->edges[$key] = $this->nodeCount++;
                }

                $node = $this->edges[$key];
            }

            $this->terminal[$node] = true;
        }
    }

    /**
     * @param String $letter
     * @return Boolean
     */
    function query($letter) {
        $this->stream .= $letter;

        if (strlen($this->stream) > $this->maxLength) {
            $this->stream = substr($this->stream, -$this->maxLength);
        }

        $node = 0;

        for ($i = strlen($this->stream) - 1; $i >= 0; --$i) {
            $key = $node * 26 + ord($this->stream[$i]) - 97;

            if (!isset($this->edges[$key])) {
                return false;
            }

            $node = $this->edges[$key];

            if (isset($this->terminal[$node])) {
                return true;
            }
        }

        return false;
